export type Role = "admin" | "member";

export interface User {
  username: string;
  password: string;
  role: Role;
}

export interface AuthOptions {
  users: User[];
  secret: string;
  now?: () => Date;
}

export function createAuthHandler(options: AuthOptions): (req: Request) => Promise<Response> {
  const { users, secret } = options;
  const now = options.now ?? (() => new Date());
  const revokedTokens = new Set<string>();

  const userMap = new Map<string, User>();
  for (const u of users) {
    userMap.set(u.username, u);
  }

  const adminCount = users.filter(u => u.role === "admin").length;
  const totalUsers = users.length;

  const encoder = new TextEncoder();
  const decoder = new TextDecoder();

  function toBase64Url(data: Uint8Array): string {
    let str = "";
    for (const b of data) {
      str += String.fromCharCode(b);
    }
    // Use btoa which is available in Deno
    return btoa(str).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
  }

  function fromBase64Url(str: string): Uint8Array {
    // Add padding
    const padded = str + "=".repeat((4 - str.length % 4) % 4);
    const binary = atob(padded.replace(/-/g, "+").replace(/_/g, "/"));
    const bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) {
      bytes[i] = binary.charCodeAt(i);
    }
    return bytes;
  }

  async function sign(payload: string): Promise<string> {
    const key = await crypto.subtle.importKey(
      "raw",
      encoder.encode(secret),
      { name: "HMAC", hash: "SHA-256" },
      false,
      ["sign"]
    );
    const sig = await crypto.subtle.sign("HMAC", key, encoder.encode(payload));
    return toBase64Url(new Uint8Array(sig));
  }

  async function verifyToken(token: string): Promise<{ username: string; role: Role } | null> {
    const parts = token.split(".");
    if (parts.length !== 2) return null;

    const [payloadB64, sigB64] = parts;

    // Recompute HMAC
    const expectedSig = await sign(payloadB64);

    // Constant-time comparison
    if (expectedSig.length !== sigB64.length) return null;
    let diff = 0;
    for (let i = 0; i < expectedSig.length; i++) {
      diff |= expectedSig.charCodeAt(i) ^ sigB64.charCodeAt(i);
    }
    if (diff !== 0) return null;

    // Decode payload
    let payloadStr: string;
    try {
      payloadStr = decoder.decode(fromBase64Url(payloadB64));
    } catch {
      return null;
    }

    let payload: any;
    try {
      payload = JSON.parse(payloadStr);
    } catch {
      return null;
    }

    if (typeof payload.u !== "string" || typeof payload.exp !== "number") return null;

    // Check expiry
    const exp = payload.exp;
    const current = now().getTime();
    if (current >= exp) return null;

    // Check revocation
    if (revokedTokens.has(token)) return null;

    // Verify user exists
    const user = userMap.get(payload.u);
    if (!user) return null;

    return { username: user.username, role: user.role };
  }

  function json(status: number, body: unknown): Response {
    return new Response(JSON.stringify(body), {
      status,
      headers: { "Content-Type": "application/json; charset=utf-8" },
    });
  }

  function getBearerToken(req: Request): string | null {
    const auth = req.headers.get("Authorization");
    if (!auth || !auth.startsWith("Bearer ")) return null;
    const token = auth.slice(7);
    if (!token || token.includes(" ")) return null;
    return token;
  }

  async function handleLogin(req: Request): Promise<Response> {
    let body: unknown;
    try {
      body = await req.json();
    } catch {
      return json(400, { error: "invalid_request" });
    }

    if (typeof body !== "object" || body === null || Array.isArray(body)) {
      return json(400, { error: "invalid_request" });
    }

    const obj = body as Record<string, unknown>;
    if (typeof obj.username !== "string" || typeof obj.password !== "string") {
      return json(400, { error: "invalid_request" });
    }

    const user = userMap.get(obj.username);
    if (!user || user.password !== obj.password) {
      return json(401, { error: "invalid_credentials" });
    }

    // Create token
    const exp = now().getTime() + 3600000;
    const nonce = crypto.getRandomValues(new Uint8Array(16));
    const nonceStr = toBase64Url(nonce);

    const payload = JSON.stringify({ u: user.username, exp, n: nonceStr });
    const payloadB64 = toBase64Url(encoder.encode(payload));
    const sig = await sign(payloadB64);
    const token = `${payloadB64}.${sig}`;

    const expiresAt = new Date(exp).toISOString();

    return json(200, { token, expiresAt });
  }

  async function handleMe(req: Request): Promise<Response> {
    const token = getBearerToken(req);
    if (!token) return json(401, { error: "unauthorized" });
    const user = await verifyToken(token);
    if (!user) return json(401, { error: "unauthorized" });
    return json(200, { username: user.username, role: user.role });
  }

  async function handleAdminStats(req: Request): Promise<Response> {
    const token = getBearerToken(req);
    if (!token) return json(401, { error: "unauthorized" });
    const user = await verifyToken(token);
    if (!user) return json(401, { error: "unauthorized" });
    if (user.role !== "admin") return json(403, { error: "forbidden" });
    return json(200, { users: totalUsers, admins: adminCount });
  }

  async function handleLogout(req: Request): Promise<Response> {
    const token = getBearerToken(req);
    if (!token) return json(401, { error: "unauthorized" });
    const user = await verifyToken(token);
    if (!user) return json(401, { error: "unauthorized" });
    revokedTokens.add(token);
    return new Response(null, { status: 204 });
  }

  return async function handler(req: Request): Promise<Response> {
    const url = new URL(req.url);
    const pathname = url.pathname;
    const method = req.method;

    if (method === "POST" && pathname === "/login") {
      return handleLogin(req);
    }
    if (method === "GET" && pathname === "/me") {
      return handleMe(req);
    }
    if (method === "GET" && pathname === "/admin/stats") {
      return handleAdminStats(req);
    }
    if (method === "POST" && pathname === "/logout") {
      return handleLogout(req);
    }

    return json(404, { error: "not_found" });
  };
}
